ALTER TABLE public.procurement_funding DROP CONSTRAINT procurement_funding_estimated_cost_check; ALTER TABLE public.procurement_funding ADD CONSTRAINT procurement_funding_estimated_cost_check CHECK(estimated_cost>0 OR (estimated_cost=0 AND stage=0)); COMMENT ON CONSTRAINT procurement_funding_estimated_cost_check ON public.procurement_funding IS 'Draft shortage requests may have an unknown zero estimate; positive cost remains mandatory once submitted to the finance approval chain.';